-- Isolated, rollback-only fixtures. Does not message or delete real learners.
begin;
do $$
declare a uuid;b uuid;c uuid;d uuid;re bigint;r jsonb;s jsonb;cursor_id bigint;mid bigint;sid uuid;nonce uuid:=gen_random_uuid();day0 text:=to_char(now() at time zone 'UTC','YYYY-MM-DD');day1 text:=to_char((now() at time zone 'UTC')-interval '1 day','YYYY-MM-DD');begin
 insert into public.bytequest_firebase_profiles(user_id,project_id,firebase_uid,email) select 'firebase:fixture:next-'||x,'fixture','next-'||x,'next-'||x||'@example.invalid' from unnest(array['a','b','c','d']) x;
 insert into public.bytequest_social_profiles(owner_id,username,display_name) values('firebase:fixture:next-a','fixture_next_a','Fixture A') returning public_id into a;
 insert into public.bytequest_social_profiles(owner_id,username,display_name) values('firebase:fixture:next-b','fixture_next_b','Fixture B') returning public_id into b;
 insert into public.bytequest_social_profiles(owner_id,username,display_name) values('firebase:fixture:next-c','fixture_next_c','Fixture C') returning public_id into c;
 insert into public.bytequest_social_profiles(owner_id,username,display_name) values('firebase:fixture:next-d','fixture_next_d','Fixture D') returning public_id into d;
 insert into public.bytequest_follows(follower,following) values(a,b),(b,a),(a,c);
 assert jsonb_array_length(public.bytequest_chat('firebase:fixture:next-a','chat-list','{}')->'users')=1,'Mutual friends only';
 cursor_id:=(public.bytequest_live_events_read('firebase:fixture:next-b',null)->>'cursor')::bigint;
 r:=public.bytequest_chat('firebase:fixture:next-a','chat-send',jsonb_build_object('target',b,'nonce',nonce,'body','Fixture hello <script>'));mid:=(r->'message'->>'id')::bigint;
 r:=public.bytequest_chat('firebase:fixture:next-a','chat-send',jsonb_build_object('target',b,'nonce',nonce,'body','Fixture hello <script>'));assert (r->'message'->>'id')::bigint=mid,'Idempotent send';
 r:=public.bytequest_live_events_read('firebase:fixture:next-b',cursor_id);assert jsonb_array_length(r->'events')=1 and (r->>'unread')::int=1,'One recipient event';
 assert jsonb_array_length(public.bytequest_live_events_read('firebase:fixture:next-d',0)->'events')=0,'No outsider events';
 r:=public.bytequest_chat('firebase:fixture:next-b','chat-thread',jsonb_build_object('target',a));assert jsonb_array_length(r->'messages')=1 and not (r->'messages'->0->>'isOwn')::boolean,'Participant-only transcript';
 perform public.bytequest_chat('firebase:fixture:next-b','chat-read',jsonb_build_object('target',a,'through',mid));assert (public.bytequest_live_events_read('firebase:fixture:next-b',0)->>'unread')::int=0,'Read cursor';
 begin perform public.bytequest_chat('firebase:fixture:next-a','chat-send',jsonb_build_object('target',c,'nonce',gen_random_uuid(),'body','Denied'));raise exception 'One-way messaging allowed';exception when insufficient_privilege then null;end;
 begin perform public.bytequest_chat('firebase:fixture:next-d','chat-thread',jsonb_build_object('target',a));raise exception 'Outsider read allowed';exception when no_data_found then null;end;
 begin perform public.bytequest_chat('firebase:fixture:next-a','chat-send',jsonb_build_object('target',b,'nonce',gen_random_uuid(),'body','Too soon'));raise exception 'Rate limit missing';exception when raise_exception then assert sqlerrm like 'Please slow%','Expected send limit';end;
 insert into public.bytequest_chat_messages(sender,recipient,client_nonce,body) select b,a,gen_random_uuid(),'Pagination fixture '||x from generate_series(1,110) x;
 r:=public.bytequest_chat('firebase:fixture:next-a','chat-thread',jsonb_build_object('target',b,'after',mid));assert jsonb_array_length(r->'messages')=50,'First delta page';cursor_id:=(r->'messages'->49->>'id')::bigint;
 r:=public.bytequest_chat('firebase:fixture:next-a','chat-thread',jsonb_build_object('target',b,'after',cursor_id));assert jsonb_array_length(r->'messages')=50,'Second delta page';cursor_id:=(r->'messages'->49->>'id')::bigint;
 r:=public.bytequest_chat('firebase:fixture:next-a','chat-thread',jsonb_build_object('target',b,'after',cursor_id));assert jsonb_array_length(r->'messages')=10,'Final delta page without gaps';
 cursor_id:=(public.bytequest_live_events_read('firebase:fixture:next-a',null)->>'cursor')::bigint;
 perform public.bytequest_update_presence_live('firebase:fixture:next-b',gen_random_uuid(),1,true,0);
 r:=public.bytequest_live_events_read('firebase:fixture:next-a',cursor_id);assert jsonb_array_length(r->'events')=1 and r->'events'->0->>'kind'='friend_online','Online transition event';
 update public.bytequest_social_profiles set show_presence=false where public_id=b;
 assert jsonb_array_length(public.bytequest_live_events_read('firebase:fixture:next-a',cursor_id)->'events')=0,'Presence privacy rechecked on delivery';
 select revision into re from public.bytequest_problems where id='two-sum' and published;
 insert into public.bytequest_firebase_progress(user_id,payload) values('firebase:fixture:next-c',jsonb_build_object('version',1,'days',jsonb_build_array(day0,day1),'solved',jsonb_build_object('two-sum',extract(epoch from now())*1000),'activity','[]'::jsonb));
 r:=public.bytequest_submissions('firebase:fixture:next-c','submission-list',jsonb_build_object('problemId','two-sum','language','java','sort','runtime'));assert not (r->>'unlocked')::boolean,'Forged progress cannot unlock sources';
 s:=jsonb_build_object('problemId','two-sum','revision',re,'language','java','source','class Solution {}','approach','Fixture approach','shared',true,'runtimeMs',1.2,'memoryBytes',20000000,'memoryMetric','process_peak_rss','compiler','openjdk-jdk-21+35','benchmarkVersion','bq-v1','suiteKind','public','testCount',5,'nonce',gen_random_uuid());
 r:=public.bytequest_submission_record('firebase:fixture:next-a',s);sid:=(r->>'id')::uuid;assert not (r?'source') and not(r?'owner_id'),'Record metadata omits source and owner';
 begin perform public.bytequest_submissions('firebase:fixture:next-c','submission-read',jsonb_build_object('id',sid));raise exception 'Unsolved read allowed';exception when insufficient_privilege then null;end;
 perform public.bytequest_submission_record('firebase:fixture:next-c',s||jsonb_build_object('nonce',gen_random_uuid(),'runtimeMs',0.9,'memoryBytes',25000000));
 r:=public.bytequest_submissions('firebase:fixture:next-c','submission-read',jsonb_build_object('id',sid));assert r->'submission'->>'source'='class Solution {}','Accepted user reads shared source';
 perform public.bytequest_submission_record('firebase:fixture:next-a',s||jsonb_build_object('nonce',gen_random_uuid(),'runtimeMs',1.0));
 r:=public.bytequest_submissions('firebase:fixture:next-c','submission-list',jsonb_build_object('problemId','two-sum','language','java','sort','runtime'));assert jsonb_array_length(r->'users')=2 and r->'users'->0->>'username'='fixture_next_c','Per-author best and runtime ordering';assert not(r->'users'->0?'source'),'No source on board';
 r:=public.bytequest_submissions('firebase:fixture:next-c','submission-list',jsonb_build_object('problemId','two-sum','language','java','sort','memory'));assert r->'users'->0->>'username'='fixture_next_a','Separate memory ordering';
 r:=public.bytequest_submissions('firebase:fixture:next-c','submission-list',jsonb_build_object('problemId','two-sum','language','python','sort','runtime'));assert jsonb_array_length(r->'users')=0,'Language isolation';
 insert into public.bytequest_firebase_progress(user_id,payload) values('firebase:fixture:next-d',jsonb_build_object('version',1,'days',jsonb_build_array(day0,day1),'solved','{}'::jsonb,'activity',jsonb_build_array(jsonb_build_object('id','two-sum','at',extract(epoch from now())*1000,'type','attempt'))));
 assert (public.bytequest_profile_activity('firebase:fixture:next-d',d::text)->>'streak')::int=0,'Attempts do not extend streak';
 update public.bytequest_firebase_progress set payload=payload||jsonb_build_object('acceptedDays',jsonb_build_array(day0,day1,'2026-02-31','2999-01-01')) where user_id='firebase:fixture:next-d';
 r:=public.bytequest_profile_activity('firebase:fixture:next-d',d::text);assert (r->>'streak')::int=2 and jsonb_array_length(r->'days')=2,'Valid consecutive accepted dates';
 assert not has_function_privilege('anon','public.bytequest_chat(text,text,jsonb)','execute'),'Browser cannot call chat RPC';
 assert not has_function_privilege('authenticated','public.bytequest_submissions(text,text,jsonb)','execute'),'Browser cannot call submission RPC';
 delete from public.bytequest_firebase_profiles where user_id='firebase:fixture:next-a';assert not exists(select 1 from public.bytequest_chat_messages where sender=a or recipient=a),'Chat deletion cascades';assert not exists(select 1 from public.bytequest_submissions where owner_id='firebase:fixture:next-a'),'Submission deletion cascades';
end $$;
rollback;
select 'PASS: chat privacy, cursors, nonces, rate limits, unread status, online privacy, solution gates, rankings, solve-only streaks and cascades' as result;
